import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function.
    """
    if x.shape != (5,):
        raise ValueError("Input x must be a NumPy array of shape (5,).")

    s = 0.0
    for i in range(-2, 3):
        for j in range(-2, 3):
            for k in range(-2, 3):
                for l in range(-2, 3):
                    for m in range(-2, 3):
                        center = np.array([i, j, k, l, m])
                        s += np.exp(-np.sum((x - center)**2) / 2)
    s *= 0.05

    s += 0.1 * np.sum(x)
    s += 0.2 * np.sin(np.sum(x))

    return float(s)
